<?php
declare(strict_types=1);
namespace BancoBrasil;
require_once __DIR__.'/ApiAbatement.php';
/** Registered amount instruction. No native invoice/receipt amount is changed by publication or confirmation. */
trait ApiAbatementAmendments
{
    public function amendAbatement($issuer,$actor,$origin,array $input,string$key):int{return $this->perform(\IssuerPolicy::id($issuer),\IssuerPolicy::id($actor),\IssuerPolicy::id($origin),'amend_abat',$key,ApiAbatement::input($input));}
    private function prepareAbatement(int$issuer,int$actor,int$originId,string$operation,?array$intent,array$snapshot,array$origin):void
    {
        $last=$this->rows("SELECT id,status FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_abat' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$originId])[0]??null;
        if(!in_array($operation,['query','movements'],true)&&$last&&!in_array($last['status'],['confirmed','rejected','auth_failed'],true))throw new \DomainException('bb_api_abatement_requires_query');
        if($operation!=='amend_abat')return;
        if(!in_array($origin['state'],['api_registered','api_query_observed'],true))throw new \DomainException('bb_api_abatement_requires_fresh_normal_query');
        $lastQuery=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='query' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$originId])[0]??null;$data=$lastQuery?json_decode($lastQuery['result_json'],true,32,JSON_THROW_ON_ERROR):[];
        if(!$lastQuery||$lastQuery['status']!=='validated'||(int)$lastQuery['http_status']!==200||!preg_match('/^[a-f0-9]{64}$/D',$lastQuery['response_hash'])||$lastQuery['updated_at']<gmdate('Y-m-d H:i:s',time()-300)||$lastQuery['updated_at']>gmdate('Y-m-d H:i:s')||($data['codigoEstadoTituloCobranca']??null)!=='1'||($data['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$data['account_evidence_hash']??''))throw new \DomainException('bb_api_abatement_requires_fresh_normal_query');
        $before=$data['bank_abatement_amount']??null;if(!is_string($before))throw new \DomainException('bb_api_abatement_query_requires_review');$old=Fields::cents($before);$amount=Fields::cents($intent['amount']);if(($intent['action']==='include'&&$old!==0)||($intent['action']==='alter'&&$old<1)||$old===$amount)throw new \DomainException('bb_api_abatement_action_conflict');if($amount>=Fields::cents($snapshot['invoice']['total']))throw new \DomainException('bb_api_abatement_exceeds_nominal');
        foreach($this->rows("SELECT result_json FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='query' AND status='validated' FOR UPDATE",[$originId])as$past){$oldQuery=json_decode($past['result_json'],true,32,JSON_THROW_ON_ERROR);if(($oldQuery['codigoEstadoTituloCobranca']??null)!=='1'||(isset($oldQuery['valorPagamentoParcialTitulo'])&&Fields::cents($oldQuery['valorPagamentoParcialTitulo'])!==0))throw new \DomainException('bb_api_abatement_adverse_history');}
        foreach($this->rows("SELECT projection_json FROM {$this->prefix}bb_api_notifications WHERE origin_id=? FOR UPDATE",[$originId])as$notification)if((json_decode($notification['projection_json'],true,32,JSON_THROW_ON_ERROR)['codigoEstadoBaixaOperacional']??null)==='10')throw new \DomainException('bb_api_abatement_adverse_history');ApiMovements::assertNoAdverseHistory($this->db,$this->prefix,$origin,true);
    }
    private function abatementQueryProjection(array$origin,array$snapshot,array$detail):array
    {
        $amount=ApiAbatement::observed($detail);$out=$amount===null?[]:['bank_abatement_amount'=>$amount];$last=$this->rows("SELECT id,status,result_json,claim_token FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_abat' AND status NOT IN ('rejected','auth_failed') ORDER BY id DESC LIMIT 1",[$origin['id']])[0]??null;if(!$last)return$out;
        $data=json_decode($last['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiAbatement::input($data['abatement']??[]);if(!hash_equals(ApiAbatement::fingerprint($origin,$snapshot,$intent),$data['abatement_fingerprint']??''))throw new \DomainException('bb_api_abatement_corrupt');if($amount===null)throw new \DomainException('bb_api_abatement_query_requires_review');if($amount===$intent['amount']){$out['abatement_id']=(string)$last['id'];if($last['status']==='sending')$out['abatement_claim_hash']=hash('sha256',$last['claim_token']);}elseif($last['status']==='confirmed')throw new \DomainException('bb_api_abatement_bank_divergence');return$out;
    }
    private function confirmAbatement(int$issuer,int$origin,array$result):void
    {
        if(!isset($result['abatement_id']))return;$id=(int)$result['abatement_id'];$last=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_abat' AND status NOT IN ('rejected','auth_failed') ORDER BY id DESC LIMIT 1 FOR UPDATE",[$origin])[0]??null;if(!$last||(int)$last['id']!==$id)throw new \DomainException('bb_api_abatement_bank_divergence');$interrupted=$last['status']==='sending'&&$last['locked_until']<=gmdate('Y-m-d H:i:s')&&preg_match('/^[a-f0-9]{64}$/D',$last['claim_token'])&&hash_equals(hash('sha256',$last['claim_token']),$result['abatement_claim_hash']??'');if(!in_array($last['status'],['validated','unknown','confirmed'],true)&&!$interrupted)throw new \DomainException('bb_api_abatement_bank_divergence');
        $data=json_decode($last['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiAbatement::input($data['abatement']??[]);[$original,,$snapshot]=$this->loadOrigin($issuer,$origin);if(!hash_equals(ApiAbatement::fingerprint($original,$snapshot,$intent),$data['abatement_fingerprint']??''))throw new \DomainException('bb_api_abatement_corrupt');if(($data['abatement_contract']??null)!==ApiAbatement::CONTRACT||!preg_match('/^[a-f0-9]{64}$/D',$data['abatement_fingerprint']??'')||($result['bank_abatement_amount']??null)!==$intent['amount']||($result['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$result['account_evidence_hash']??''))throw new \DomainException('bb_api_abatement_bank_divergence');$data['bank_state']='abatement_confirmed';$data['account_evidence_hash']=$result['account_evidence_hash'];$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);\IssuerStorage::query($this->db,"UPDATE {$this->prefix}bb_api_operations SET status='confirmed',result_json=?,updated_at=? WHERE id=?",[$json,gmdate('Y-m-d H:i:s'),$id]);$saved=$this->rows("SELECT status,result_json FROM {$this->prefix}bb_api_operations WHERE id=?",[$id])[0]??[];if(($saved['status']??null)!=='confirmed'||($saved['result_json']??null)!==$json)throw new \RuntimeException('issuer_bb_api_write_unconfirmed');
    }
}
